#include <iomanip>
#include <iostream>

class Qty {
public:
    explicit Qty(int n) : n_(n) {}
    int value() const { return n_; }

private:
    int n_;
};

class Price {
public:
    explicit Price(double px) : px_(px) {}
    explicit operator double() const { return px_; }

private:
    double px_;
};

class Order {
public:
    Order(Qty qty, Price price) : qty_(qty), price_(price) {}
    explicit operator bool() const { return qty_.value() > 0; }
    double notional() const { return qty_.value() * static_cast<double>(price_); }

private:
    Qty qty_;
    Price price_;
};

void send(const Order& order) {
    if (!order) {
        std::cout << "skipped an empty order\n";
        return;
    }
    std::cout << "sent, notional " << order.notional() << '\n';
}

int main() {
    std::cout << std::fixed << std::setprecision(2);
    send(Order(Qty(100), Price(101.25)));
    send(Order(Qty(0), Price(99.50)));
    // send(Order(101.25, 100));  // does not compile: both constructors are explicit
    const bool live = static_cast<bool>(Order(Qty(5), Price(10.0)));
    std::cout << std::boolalpha << "live " << live << '\n';
    return 0;
}

