#include <iostream>
#include <string>

enum class Side { Buy = 1, Sell = 2 };

// From an old C library: it only reads msg, but it was declared without const.
int fixChecksum(char* msg) {
    int sum = 0;
    for (char* p = msg; *p != '\0'; ++p) {
        sum += static_cast<unsigned char>(*p);
    }
    return sum % 256;
}

int checksumOf(const std::string& msg) {
    return fixChecksum(const_cast<char*>(msg.c_str()));  // safe: it never writes
}

int main() {
    const double price = 101.257;
    std::cout << "cents " << static_cast<long long>(price * 100 + 0.5) << '\n';
    std::cout << "side " << static_cast<int>(Side::Sell) << '\n';
    const Side side = static_cast<Side>(1);
    std::cout << "buy? " << (side == Side::Buy ? "yes" : "no") << '\n';
    std::cout << "checksum " << checksumOf("35=D|55=AAPL|") << '\n';

    const std::uint32_t qty = 100000;
    const auto* bytes = reinterpret_cast<const unsigned char*>(&qty);
    std::cout << "qty bytes";
    for (std::size_t i = 0; i < sizeof(qty); ++i) {
        std::cout << ' ' << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(bytes[i]);
    }
    std::cout << std::dec << '\n';
    return 0;
}

