#include <iostream>
#include <memory>
#include <string>
#include <typeinfo>
#include <vector>

class Message {
public:
    virtual ~Message() = default;
};

class NewOrder : public Message {
public:
    explicit NewOrder(int qty) : qty_(qty) {}
    int qty() const { return qty_; }

private:
    int qty_;
};

class Cancel : public Message {
public:
    explicit Cancel(int id) : id_(id) {}
    int id() const { return id_; }

private:
    int id_;
};

int main() {
    std::vector<std::unique_ptr<Message>> inbox;
    inbox.push_back(std::make_unique<NewOrder>(100));
    inbox.push_back(std::make_unique<Cancel>(7));
    inbox.push_back(std::make_unique<NewOrder>(50));
    int ordered = 0;
    for (const auto& m : inbox) {
        if (const auto* order = dynamic_cast<const NewOrder*>(m.get())) {
            ordered += order->qty();
        } else if (const auto* cancel = dynamic_cast<const Cancel*>(m.get())) {
            std::cout << "cancel order " << cancel->id() << '\n';
        }
    }
    std::cout << "ordered " << ordered << '\n';
    try {
        const Cancel& c = dynamic_cast<const Cancel&>(*inbox[0]);
        std::cout << "first is cancel " << c.id() << '\n';
    } catch (const std::bad_cast& e) {
        std::cout << "first is not a cancel: " << e.what() << '\n';
    }
    return 0;
}

