#include <iomanip>
#include <iostream>
#include <memory>
#include <string>
#include <typeinfo>
#include <vector>

class Event {
public:
    virtual ~Event() = default;
};

class Trade : public Event {
public:
    explicit Trade(int qty) : qty_(qty) {}
    int qty() const { return qty_; }

private:
    int qty_;
};

class Quote : public Event {
public:
    Quote(double bid, double ask) : bid_(bid), ask_(ask) {}
    double bid() const { return bid_; }
    double ask() const { return ask_; }

private:
    double bid_;
    double ask_;
};

class Heartbeat : public Event {};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<std::unique_ptr<Event>> events;
    for (int i = 0; i < n; ++i) {
        std::string kind;
        std::cin >> kind;
        if (kind == "trade") {
            int qty = 0;
            std::cin >> qty;
            events.push_back(std::make_unique<Trade>(qty));
        } else if (kind == "quote") {
            double bid = 0.0;
            double ask = 0.0;
            std::cin >> bid >> ask;
            events.push_back(std::make_unique<Quote>(bid, ask));
        } else {
            events.push_back(std::make_unique<Heartbeat>());
        }
    }
    std::cout << std::fixed << std::setprecision(2);
    int volume = 0;
    for (const auto& e : events) {
        if (const auto* trade = dynamic_cast<const Trade*>(e.get())) {
            volume += trade->qty();
        } else if (const auto* quote = dynamic_cast<const Quote*>(e.get())) {
            std::cout << "quote " << quote->bid() << ' ' << quote->ask() << '\n';
        }
    }
    std::cout << "volume " << volume << '\n';
    try {
        const Trade& last = dynamic_cast<const Trade&>(*events.back());
        std::cout << "last trade " << last.qty() << '\n';
    } catch (const std::bad_cast&) {
        std::cout << "last event is not a trade\n";
    }
    return 0;
}
